import {dependencyNetwork,networkView,networkLayout,equipmentNodeState} from './dependency-network.js';
import {eligibility} from './experiment-definitions.js';
import {EQUIPMENT} from './equipment-catalog.js';
import {escapeText as safe} from './progression-ui.js';
import {graphEdgePath} from './experiment-definitions.js';
const lines=name=>{const words=name.split(' '),out=[''];for(const word of words){if((out.at(-1)+' '+word).trim().length>22&&out.length<2)out.push(word);else out[out.length-1]=(out.at(-1)+' '+word).trim();}return out.map(line=>line.length>23?line.slice(0,22)+'…':line);};
export function mapMarkup(player,selected,focused){
 const graph=dependencyNetwork(),view=networkView(graph,selected,focused),layout=networkLayout(view);
 const ancestors=new Set([selected]);let changed=true;while(changed){changed=false;for(const edge of graph.edges)if(ancestors.has(edge.to)&&!ancestors.has(edge.from)){ancestors.add(edge.from);changed=true;}}
 const nodes=layout.nodes.map(n=>{
  const r=n.type==='experiment'?eligibility(player,n.id):equipmentNodeState(player,n),label=r.label;
  return `<g class="experiment-node network-${n.type}${ancestors.has(n.id)?' on-path':''}" data-node="${n.id}" ${n.type==='experiment'?`data-experiment="${n.id}"`:`data-network-gear="${n.id}"`} data-state="${r.state}" tabindex="0" role="button" aria-label="${safe(n.name+': '+label)}" transform="translate(${n.x} ${n.y})"><rect width="165" height="66" rx="${n.type==='equipment'?3:12}"/>${lines(n.name).map((line,i)=>`<text x="9" y="${18+i*16}">${safe(line)}</text>`).join('')}<text class="node-status" x="9" y="55">${safe(label)}</text><title>${safe(n.name)}${n.type==='equipment'?': '+Object.entries(n.equipment).map(([id,n])=>n+' × '+EQUIPMENT[id].name).join(', '):''}</title></g>`;
 }).join('');
 const edges=layout.edges.map(edge=>`<path class="network-edge${ancestors.has(edge.from)&&ancestors.has(edge.to)?' on-path':''}" d="${graphEdgePath(layout.nodes,edge)}" fill="none" stroke-linejoin="round" marker-end="url(#equipment-arrow)" data-equipment-from="${edge.from}" data-equipment-to="${edge.to}"><title>${safe(edge.label)}</title></path>`).join('');
 return{layout,html:`<p class="network-explanation"><strong>Equipment combines to open laboratories.</strong> Follow equipment branches into an experiment: every incoming requirement is needed. Reusable items stay owned. Supplies are checked separately; earlier lab completion is not required.</p><div class="network-tools"><button data-action="map-network">${focused?'Show whole network':'Focus selected lab'}</button><button data-action="map-reset">Fit map</button><button data-map-zoom="1.2" aria-label="Zoom in">＋</button><button data-map-zoom="0.833333" aria-label="Zoom out">−</button><button data-map-pan="left" aria-label="Pan left">←</button><button data-map-pan="right" aria-label="Pan right">→</button><button data-map-pan="up" aria-label="Pan up">↑</button><button data-map-pan="down" aria-label="Pan down">↓</button><span>${focused?'Selected lab requirements':'All equipment branches'} · drag to pan</span></div><div class="map-legend"><span>▧ Equipment group</span><span>▢ Experiment</span><span data-state="completed">Owned / completed</span><span data-state="available">Available</span><span data-state="missing-equipment">Missing equipment</span><span data-state="missing-materials">Missing consumables</span></div><svg id="progression-map" viewBox="0 0 950 620" aria-label="Shared equipment and laboratory dependency network" tabindex="0"><defs><marker id="equipment-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#597d73"/></marker></defs><g id="map-camera">${edges}${nodes}</g></svg>`};
}
export function gearDetails(player,id){
 const graph=dependencyNetwork(),node=graph.nodes.find(n=>n.id===id&&n.type==='equipment');if(!node)return '';
 const consumers=graph.nodes.filter(n=>n.type==='experiment'&&node.consumers.includes(n.id));
 return `<h3>${safe(node.name)}</h3><p>Reusable equipment shared by ${consumers.length} ${consumers.length===1?'experiment':'experiments'}. All items below are needed for this group.</p><ul>${Object.entries(node.equipment).map(([key,n])=>`<li>${safe(EQUIPMENT[key].name)} × ${n} · owned ${player.equipment[key]||0}</li>`).join('')}</ul><h4>Used in</h4><div class="panel-actions">${consumers.map(n=>`<button data-experiment="${n.id}">${safe(n.name)}</button>`).join('')}</div><button data-action="shop">View equipment in the shop</button>`;
}
